// PLAYWRIGHT_MODULE=<index.mjs> node packages/web/test/fixtures/composer-pending-browser.mjs <url> <evidence>
import assert from "node:assert/strict";
import { mkdirSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
const { chromium } = await import(process.env.PLAYWRIGHT_MODULE ?? "playwright");
const url = process.argv[2];
const evidence = resolve(process.argv[3] ?? "docs/acceptance/composer-pending-2026-10-02");
mkdirSync(evidence, { recursive: true });
const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
await context.addInitScript(() => localStorage.setItem("excelmanus.onboarding", "done"));
const page = await context.newPage();
const errors = [];
const results = [];
page.on("pageerror", (e) => errors.push(e.message));
const record = (name) => results.push({ name, passed: true });
const api = async (path, options) => {
  const response = await context.request.fetch(`${url}/api/v1/${path}`, options);
  assert(response.ok(), `${path}: ${response.status()} ${await response.text()}`);
  return response.json();
};
const wait = async (predicate, name) => {
  const until = Date.now() + 10000;
  while (!(await predicate())) { assert(Date.now() < until, name); await page.waitForTimeout(50); }
};
const input = () => page.locator("#composer-input");
const model = () => page.getByRole("button", { name: "当前代理使用的模型档案（与 /model 相同，从下一步生效）", exact: true });
const send = async (text) => { await input().fill(text); await page.getByRole("button", { name: "发送", exact: true }).click(); };
const pending = (text) => page.locator(".pending-message").filter({ hasText: text });
const shot = async (name) => { await page.waitForTimeout(250); await page.screenshot({ path: resolve(evidence, `${name}.png`) }); };
let sessionId;
const logs = async () => (await api(`sessions/${sessionId}/log`)).items;
const statuses = async () => Object.fromEntries((await logs()).filter((r) => r.type === "dispatch.updated").map((r) => [r.data.dispatchId, r.data.status]));
const pause = () => page.getByRole("button", { name: "暂停", exact: true });
const longTask = async () => { await send("长任务"); await pause().waitFor(); await page.getByText("正在处理长任务…", { exact: true }).last().waitFor(); };
try {
  await page.goto(url);
  await page.getByRole("button", { name: /^气泡验收/ }).click();
  await model().waitFor();
  sessionId = (await api("sessions")).items.find((s) => s.title === "气泡验收").id;
  await model().click();
  await page.getByRole("radio", { name: /GPT-6 Astra/ }).waitFor();
  await shot("model-menu");
  await page.getByRole("radio", { name: /GPT-6 Astra/ }).focus();
  await page.keyboard.press("Space");
  await wait(async () => (await model().innerText()).includes("GPT-6 Astra"), "keyboard model switch");
  await model().click();
  await page.getByRole("radio", { name: /GPT-6.1 Sol/ }).click();
  await wait(async () => (await model().innerText()).includes("GPT-6.1 Sol"), "model switched back");
  record("combined model menu switches real agent profile with mouse and keyboard");
  await model().click();
  await page.getByRole("button", { name: "思考等级", exact: true }).click();
  const slider = () => page.getByRole("slider", { name: "思考等级", exact: true });
  await slider().waitFor();
  await shot("reasoning-high");
  const profile = (await api("model-profiles")).items.find((p) => p.isDefault);
  for (const [index, level] of [[0, "none"], [1, "low"], [2, "medium"], [3, "high"], [4, "xhigh"], [5, "max"]]) {
    await slider().focus();
    await page.keyboard.press(index < 3 ? "Home" : "End");
    await wait(() => model().isEnabled(), "slider saving");
    while (Number(await slider().getAttribute("aria-valuenow")) !== index) {
      await slider().press(Number(await slider().getAttribute("aria-valuenow")) < index ? "ArrowRight" : "ArrowLeft");
      await wait(() => model().isEnabled(), "slider arrow saving");
    }
    assert.equal((await api("model-profiles")).items.find((p) => p.id === profile.id).reasoning, level);
  }
  await page.getByRole("button", { name: "恢复默认思考等级", exact: true }).click();
  await wait(() => model().isEnabled(), "reasoning reset");
  assert.equal((await api("model-profiles")).items.find((p) => p.id === profile.id).reasoning, "provider-default");
  await slider().focus();
  await slider().press("End");
  await wait(() => model().isEnabled(), "max saving");
  await slider().press("ArrowLeft");
  await wait(() => model().isEnabled(), "xhigh saving");
  await slider().press("ArrowLeft");
  await wait(() => model().isEnabled(), "high saving");
  await page.keyboard.press("Escape");
  await page.reload();
  await wait(async () => (await model().innerText()).includes("高"), "reasoning reload");
  record("six slider stops and reset save to actual model profile and survive refresh");

  await page.getByRole("button", { name: /^设置/ }).click();
  const dialog = page.getByRole("dialog");
  await dialog.getByRole("button", { name: "权限与运行", exact: true }).click();
  await dialog.getByRole("combobox", { name: "运行中消息的默认行为", exact: true }).click();
  await page.getByRole("option", { name: "排队", exact: true }).click();
  await dialog.getByRole("button", { name: "保存", exact: true }).click();
  await wait(async () => (await api("settings")).settings.defaultDispatchMode === "queue", "default queue save");
  await dialog.getByRole("button", { name: "关闭", exact: true }).click();
  record("default dispatch is configured in settings and saved through real HTTP");
  await longTask();
  assert.equal(await page.locator(".composer-toolbar button").filter({ hasText: /引导|排队|打断/ }).count(), 0);
  assert.equal(await page.locator(".composer-submit").count(), 1);
  await page.waitForTimeout(4200);
  await shot("pause");
  const png = { name: "pixel.png", mimeType: "image/png", buffer: Buffer.from("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jRZkAAAAASUVORK5CYII=", "base64") };
  await page.locator('input[type="file"][multiple]').setInputFiles(png);
  await wait(async () => !(await page.getByText("上传中…", { exact: true }).count()), "image upload");
  await send("这条排队消息可以编辑");
  await pending("这条排队消息可以编辑").waitFor();
  await shot("pending-queue");
  const statusBox = await pending("这条排队消息可以编辑").locator("[role=status]").boundingBox();
  assert(statusBox.width <= 1 && statusBox.height <= 1, "dispatch status must have no visible purple line");
  const original = (await logs()).filter((r) => r.type === "user.message").at(-1).data;
  assert.equal(original.mode, "queue");
  await pending("这条排队消息可以编辑").getByRole("button", { name: "编辑待处理消息", exact: true }).click();
  await page.getByRole("textbox", { name: "编辑待处理消息", exact: true }).fill("修改后的排队消息 @data.csv");
  await page.getByRole("button", { name: "保存消息", exact: true }).click();
  await pending("修改后的排队消息 @data.csv").waitFor();
  const edited = (await logs()).filter((r) => r.type === "user.message").at(-1).data;
  assert.equal(edited.replacesDispatchId, original.dispatchId);
  assert.deepEqual(edited.attachments, original.attachments);
  assert.equal((await statuses())[original.dispatchId], "cancelled");
  await page.reload();
  await pending("修改后的排队消息 @data.csv").waitFor();
  record("queued bubble edits atomically, preserves image attachment and survives reload");
  await pending("修改后的排队消息 @data.csv").getByRole("button", { name: "删除消息", exact: true }).click();
  await wait(async () => (await pending("修改后的排队消息 @data.csv").count()) === 0, "deleted bubble hidden");
  assert.equal((await statuses())[edited.dispatchId], "cancelled");
  record("delete hides cancelled bubble while append-only log preserves original and edited content");
  await send("暂停后保留的排队消息");
  await pending("暂停后保留的排队消息").waitFor();
  await pause().click();
  await wait(async () => (await pause().count()) === 0, "pause ended task");
  await pending("暂停后保留的排队消息").waitFor();
  assert(await page.getByRole("button", { name: "继续发送", exact: true }).isVisible());
  await pending("暂停后保留的排队消息").getByRole("button", { name: "打断并发送", exact: true }).click();
  await page.getByText("收到：暂停后保留的排队消息", { exact: true }).waitFor();
  record("round pause button stops current task, queue remains and bubble can send directly");

  await api("settings", { method: "PATCH", data: { defaultDispatchMode: "steer" } });
  await longTask();
  await send("这条引导消息尚未送达");
  await pending("这条引导消息尚未送达").waitFor();
  assert.equal((await logs()).filter((r) => r.type === "user.message").at(-1).data.mode, "steer");
  await pending("这条引导消息尚未送达").getByRole("button", { name: "编辑待处理消息", exact: true }).click();
  await page.getByRole("textbox", { name: "编辑待处理消息", exact: true }).fill("编辑后立即发送");
  await page.route("**/agents/main/messages", (route) => route.abort());
  await page.getByRole("button", { name: "保存消息", exact: true }).click();
  await wait(() => page.getByRole("button", { name: "保存消息", exact: true }).isEnabled(), "failed edit busy release");
  assert.equal(await page.getByRole("textbox", { name: "编辑待处理消息", exact: true }).inputValue(), "编辑后立即发送");
  assert.equal((await logs()).filter((r) => r.type === "user.message").at(-1).data.text, "这条引导消息尚未送达");
  await page.unroute("**/agents/main/messages");
  await page.getByRole("button", { name: "打断并发送", exact: true }).click();
  await page.getByText("收到：编辑后立即发送", { exact: true }).waitFor();
  assert.equal((await logs()).filter((r) => r.type === "user.message").at(-1).data.mode, "interrupt");
  record("steer bubble shows pending status, failed edit preserves draft, interrupt sends edited content once");
  await api("settings", { method: "PATCH", data: { defaultDispatchMode: "interrupt" } });
  await longTask();
  await input().fill("默认打断消息");
  await input().press("Enter");
  await page.getByText("收到：默认打断消息", { exact: true }).waitFor();
  assert.equal((await logs()).filter((r) => r.type === "user.message").at(-1).data.mode, "interrupt");
  record("single send button and Enter semantics honor default interrupt without extra strategy buttons");
  await page.route("**/agents/main/messages", (route) => route.abort());
  await send("网络失败保留草稿");
  await wait(async () => (await input().inputValue()) === "网络失败保留草稿", "failed send draft");
  assert.equal(await pending("网络失败保留草稿").count(), 0);
  await page.unroute("**/agents/main/messages");
  await send("网络失败保留草稿");
  await page.getByText("收到：网络失败保留草稿", { exact: true }).waitFor();
  record("network failure retains composer draft, retry sends once without falsely showing a delivered message");

  await page.getByRole("button", { name: "切换深色 / 浅色", exact: true }).click();
  await model().click();
  await shot("model-dark");
  await page.getByRole("button", { name: "思考等级", exact: true }).click();
  await shot("reasoning-dark");
  await page.keyboard.press("Escape");
  await page.getByRole("button", { name: "切换深色 / 浅色", exact: true }).click();
  await page.setViewportSize({ width: 420, height: 850 });
  await model().click();
  await shot("model-narrow");
  const pop = await page.locator('[data-slot="popover"]').boundingBox();
  assert(pop.x >= 0 && pop.x + pop.width <= 420);
  await page.keyboard.press("Escape");
  await shot("narrow");
  await page.getByRole("button", { name: /收起侧栏/ }).click();
  await shot("narrow-sidebar-collapsed");
  assert(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth));
  const modelBox = await model().boundingBox();
  const sendBox = await page.locator(".composer-submit").boundingBox();
  assert(modelBox.x + modelBox.width <= sendBox.x || modelBox.y + modelBox.height <= sendBox.y || sendBox.y + sendBox.height <= modelBox.y, "toolbar overlap");
  record("narrow viewport keeps model popover and single action button within bounds");
  assert.deepEqual(errors, []);
  record("no browser runtime errors");
  writeFileSync(resolve(evidence, "browser-results.json"), `${JSON.stringify({ results, errors }, null, 2)}\n`);
  process.stdout.write(`${JSON.stringify({ passed: results.length, evidence })}\n`);
} catch (error) { await shot("failure"); throw error; }
finally { await browser.close(); }
